func testOperacaofiscalToManyAddOpOpfConhecimentoTransportes(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Operacaofiscal
	var b, c, d, e ConhecimentoTransporte

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, operacaofiscalDBTypes, false, strmangle.SetComplement(operacaofiscalPrimaryKeyColumns, operacaofiscalColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*ConhecimentoTransporte{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, conhecimentoTransporteDBTypes, false, strmangle.SetComplement(conhecimentoTransportePrimaryKeyColumns, conhecimentoTransporteColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*ConhecimentoTransporte{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddOpfConhecimentoTransportes(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.OpfID != first.OpfID {
			t.Error("foreign key was wrong value", a.OpfID, first.OpfID)
		}
		if a.OpfID != second.OpfID {
			t.Error("foreign key was wrong value", a.OpfID, second.OpfID)
		}

		if first.R.Opf != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Opf != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.OpfConhecimentoTransportes[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.OpfConhecimentoTransportes[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.OpfConhecimentoTransportes().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}
