func testOperacaofiscalToOneCsticmUsingCsticm(t *testing.T) {
	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var local Operacaofiscal
	var foreign Csticm

	seed := randomize.NewSeed()
	if err := randomize.Struct(seed, &local, operacaofiscalDBTypes, true, operacaofiscalColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Operacaofiscal struct: %s", err)
	}
	if err := randomize.Struct(seed, &foreign, csticmDBTypes, false, csticmColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Csticm struct: %s", err)
	}

	if err := foreign.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	queries.Assign(&local.CsticmsID, foreign.CsticmsID)
	if err := local.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	check, err := local.Csticm().One(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}

	if !queries.Equal(check.CsticmsID, foreign.CsticmsID) {
		t.Errorf("want: %v, got %v", foreign.CsticmsID, check.CsticmsID)
	}

	ranAfterSelectHook := false
	AddCsticmHook(boil.AfterSelectHook, func(ctx context.Context, e boil.ContextExecutor, o *Csticm) error {
		ranAfterSelectHook = true
		return nil
	})

	slice := OperacaofiscalSlice{&local}
	if err = local.L.LoadCsticm(ctx, tx, false, (*[]*Operacaofiscal)(&slice), nil); err != nil {
		t.Fatal(err)
	}
	if local.R.Csticm == nil {
		t.Error("struct should have been eager loaded")
	}

	local.R.Csticm = nil
	if err = local.L.LoadCsticm(ctx, tx, true, &local, nil); err != nil {
		t.Fatal(err)
	}
	if local.R.Csticm == nil {
		t.Error("struct should have been eager loaded")
	}

	if !ranAfterSelectHook {
		t.Error("failed to run AfterSelect hook for relationship")
	}
}

